#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
F1="$GSZ/lib/botapi.js"
F2="$GSZ/routes/checkout.js"
TS=$(date +%Y%m%d-%H%M%S)
BK1="$F1.bak-step190-$TS"; BK2="$F2.bak-step190-$TS"
echo "==> step190: PLAYER ACTIVATION ENGINE (credit-safe activate-player + poll)"
cp "$F1" "$BK1"; cp "$F2" "$BK2"; echo "    backups: $BK1 , $BK2"
restore(){ echo "!! restoring"; cp "$BK1" "$F1" 2>/dev/null||true; cp "$BK2" "$F2" 2>/dev/null||true; }
trap 'restore' ERR
echo "==> applying patcher"
P=$(mktemp /tmp/p190.XXXXXX.js); echo "" | base64 -d > "$P"
NODE_PATH="$GSZ/node_modules" node "$P" "$GSZ"
echo "==> validating"
NODE_PATH="$GSZ/node_modules" node --check "$F1" && echo "    botapi.js ok"
NODE_PATH="$GSZ/node_modules" node --check "$F2" && echo "    checkout.js ok"
echo "==> verifying embedded patcher matches source"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE"; false; }
echo "    homepage 200: OK (after ${i}s)"
rm -f "$P"; trap - ERR
echo ""
echo "==> step190 OK  Player orders (hotplayer/ibosol/zayron) that carry a bot plan_key now auto-activate via /api/activate-player with a stable activation_id (no double-charge), poll /api/activate-status, and deliver the returned credential block on WhatsApp + email. Players without a plan_key are unchanged. Next: wire the duration plans + prices so activation turns on."
